class _UniffiConverterBool:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)

class _UniffiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()










class AddressRecord:
    """
    One decoded address (`{osm_id, housenumber, street}`; location is the cell).
    """

    osm_id: "int"
    housenumber: "str"
    street: "str"
    def __init__(self, *, osm_id: "int", housenumber: "str", street: "str"):
        self.osm_id = osm_id
        self.housenumber = housenumber
        self.street = street

    def __str__(self):
        return "AddressRecord(osm_id={}, housenumber={}, street={})".format(self.osm_id, self.housenumber, self.street)

    def __eq__(self, other):
        if self.osm_id != other.osm_id:
            return False
        if self.housenumber != other.housenumber:
            return False
        if self.street != other.street:
            return False
        return True

